  "check_code": "#!/usr/bin/env python3
"""Deterministic post-state checks for the SAP EWM annotation task."""


import re
import sqlite3
import hashlib
import json
from datetime import datetime
from pathlib import Path


TARGET_LINE = "RL-25-0902-CAN"
TARGET_CONTROL = "CN-IN-25-0902-002"


def _db_path(workspace, backup=False):
    name = "state.db.pinned_backup" if backup else "state.db"
    return Path(workspace).resolve().parent / "system" / "sap_s4_ewm" / name


def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _query_one(path, sql, params=()):
    con = sqlite3.connect(str(path))
    con.row_factory = sqlite3.Row
    try:
        row = con.execute(sql, tuple(params)).fetchone()
        return dict(row) if row else None
    finally:
        con.close()


def _has_concept(text, alternatives):
    normalized = _norm(text)
    return any(all(token in normalized for token in option) for option in alternatives)


def check_target_annotation(workspace):
    row = _query_one(
        _db_path(workspace),
        """SELECT discrepancy_code, discrepancy_qty_ea, buyer_notification_reference,
                  annotation_text, annotated_by, annotated_at
             FROM receipt_lines WHERE receipt_line_id=?""",
        (TARGET_LINE,),
    )
    if not row:
        return {"score": 0, "detail": "The target receipt line is missing."}

    failures = []
    code = _norm(row["discrepancy_code"])
    if "audit" not in code or "cancel" not in code:
        failures.append("classification does not express both audit-only and canceled-document treatment")
    if row["discrepancy_qty_ea"] != 800:
        failures.append("discrepancy quantity is not the full retained 800 EA")

    reference = _norm(row["buyer_notification_reference"])
    if not all(token in reference for token in ("cn", "in", "25", "0902", "002")):
        failures.append("buyer reference is not traceable to CN-IN-25-0902-002")
    if not ("clause" in reference and "330" in reference):
        failures.append("buyer reference is not traceable to Boeing Clause 330")

    note = row["annotation_text"]
    if not _has_concept(note, [("audit", "retain"), ("audit", "evidence"), ("traceability",)]):
        failures.append("annotation does not explain audit retention or traceability")
    if "cancel" not in _norm(note):
        failures.append("annotation does not identify the canceled parent document")
    if not _has_concept(note, [("excluded", "recogn"), ("exclude", "recogn"), ("excluding", "recogn"), ("excludes", "recogn"), ("not", "recogn"), ("does", "not", "count"), ("no", "receipt", "recognition")]):
        failures.append("annotation does not explain exclusion from recognized receipts")
    if not str(row["annotated_by"] or "").strip():
        failures.append("annotator is blank")
    try:
        datetime.fromisoformat(str(row["annotated_at"]).replace("Z", "+00:00"))
    except Exception:
        failures.append("annotation timestamp is missing or not ISO 8601")

    if failures:
        return {"score": 0, "detail": "; ".join(failures)}
    return {"score": 1, "detail": "The target line has a complete audit-only canceled-document annotation for 800 EA with traceable buyer reference."}


def check_target_document_preserved(workspace):
    row = _query_one(
        _db_path(workspace),
        """SELECT h.posting_status AS header_status, r.receipt_status,
                  r.received_qty_ea, r.scanner_duplicate_flag
             FROM shipment_headers h JOIN receipt_lines r ON r.shipment_id=h.shipment_id
            WHERE h.control_number=? AND r.receipt_line_id=?""",
        (TARGET_CONTROL, TARGET_LINE),
    )
    expected = {
        "header_status": "CANCELED",
        "receipt_status": "POSTED_ACCEPTED",
        "received_qty_ea": 800,
        "scanner_duplicate_flag": 0,
    }
    if row != expected:
        return {"score": 0, "detail": f"Target document or receipt values changed: {row!r}"}
    return {"score": 1, "detail": "The canceled header, accepted retained line, quantity, and duplicate flag are preserved."}


def check_other_receipts_unchanged(workspace):
    columns = """receipt_line_id, shipment_id, received_qty_ea, receipt_status,
                 scanner_duplicate_flag, discrepancy_code, discrepancy_qty_ea,
                 buyer_notification_reference, annotation_text, annotated_by, annotated_at"""
    con = sqlite3.connect(str(_db_path(workspace)))
    try:
        current = con.execute(
            f"SELECT {columns} FROM receipt_lines WHERE receipt_line_id<>? ORDER BY receipt_line_id",
            (TARGET_LINE,),
        ).fetchall()
    finally:
        con.close()
    payload = json.dumps(current, ensure_ascii=False, separators=(",", ":"))
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
    if len(current) != 129 or digest != "4f166d7fc9aa608cd4d72533e7637ba60e9792b007e77da1034e4102fe779c04":
        return {"score": 0, "detail": "At least one non-target receipt line was added, removed, or changed."}
    return {"score": 1, "detail": "All non-target receipt lines match the pinned baseline."}
